import 'package:flutter/foundation.dart';
import '../core/models/models.dart';
import '../core/storage/app_storage.dart';

/// Result of auto-deduplication containing cleaned entities and retired IDs.
class AutoDeduplicationResult<T> {
  final List<T> cleaned;
  final Set<String> retiredIds;

  const AutoDeduplicationResult({
    required this.cleaned,
    required this.retiredIds,
  });
}

/// Service providing silent background reconciliation to detect and retire
/// redundant duplicate records generated by monthly roll syncs or cross-device merges.
class AutoDeduplicationService {
  AutoDeduplicationService._();

  static String _monthKey(String? dateStr) {
    if (dateStr == null || dateStr.length < 7) return '';
    return dateStr.substring(0, 7);
  }

  static String _expSig(String cat, String desc, double amt) =>
      '${cat.trim().toLowerCase()}_${desc.trim().toLowerCase()}_$amt';

  /// Reconciles payments across all months.
  ///
  /// Rules:
  /// 1. If a tenant has both 'paid' and 'pending' records for the same month,
  ///    the pending record is a redundant sync artifact and is retired.
  /// 2. If multiple 'pending' records exist for the same month without payments,
  ///    the canonical record (matching tenant rent amount or first created) is kept.
  /// 3. Legitimate installment payments (multiple 'paid' records on different dates)
  ///    are preserved.
  static AutoDeduplicationResult<Payment> reconcilePayments(
    List<Payment> payments, {
    Map<String, Tenant>? tenantById,
  }) {
    if (payments.isEmpty) {
      return const AutoDeduplicationResult(cleaned: [], retiredIds: {});
    }

    // Group by tenantId + monthKey
    final groups = <String, List<Payment>>{};
    for (final p in payments) {
      final m = _monthKey(p.paidForMonth ?? p.displayMonth ?? p.paidDate);
      if (p.tenantId.isEmpty || m.isEmpty) {
        // Entries without valid tenant or month are kept as-is
        groups.putIfAbsent('raw_${p.id}', () => []).add(p);
      } else {
        groups.putIfAbsent('${p.tenantId}_$m', () => []).add(p);
      }
    }

    final cleaned = <Payment>[];
    final retired = <String>{};

    for (final list in groups.values) {
      if (list.length <= 1) {
        cleaned.addAll(list);
        continue;
      }

      final hasPaid = list.any((p) => p.status == 'paid');
      if (hasPaid) {
        // Keep all paid records (preserves installments). Only retire a pending
        // record when a paid record already covers the exact same amount; a
        // separate outstanding balance must survive.
        final paidTotal = list
            .where((p) => p.status == 'paid')
            .fold<double>(0, (sum, p) => sum + p.amount);
        for (final p in list) {
          if (p.status == 'paid') {
            cleaned.add(p);
          } else if (paidTotal >= p.amount - 0.01) {
            // The pending row is fully covered by recorded payments.
            retired.add(p.id);
          } else {
            // Genuine outstanding balance; keep it.
            cleaned.add(p);
          }
        }
      } else {
        // All are pending: select best canonical entry to keep
        final tenant = tenantById != null ? tenantById[list.first.tenantId] : null;
        final targetRent = tenant?.rentAmount ?? -1;

        Payment? keep;
        if (targetRent > 0) {
          final matching = list.where((p) => p.amount == targetRent).toList();
          if (matching.isNotEmpty) {
            keep = matching.first;
          }
        }
        keep ??= list.first;

        for (final p in list) {
          if (p.id == keep.id) {
            cleaned.add(p);
          } else {
            retired.add(p.id);
          }
        }
      }
    }

    return AutoDeduplicationResult(
      cleaned: cleaned,
      retiredIds: retired,
    );
  }

  /// Reconciles recurring expenses across all months.
  ///
  /// Retires identical pending expenses created for the same category,
  /// description, amount, and month.
  static AutoDeduplicationResult<Expense> reconcileExpenses(List<Expense> expenses) {
    if (expenses.isEmpty) {
      return const AutoDeduplicationResult(cleaned: [], retiredIds: {});
    }

    final groups = <String, List<Expense>>{};
    for (final e in expenses) {
      final m = _monthKey(e.expenseForMonth ?? e.displayMonth ?? e.date);
      final sig = _expSig(e.category, e.description, e.amount);
      if (m.isEmpty) {
        groups.putIfAbsent('raw_${e.id}', () => []).add(e);
      } else {
        groups.putIfAbsent('${sig}_$m', () => []).add(e);
      }
    }

    final cleaned = <Expense>[];
    final retired = <String>{};

    for (final list in groups.values) {
      if (list.length <= 1) {
        cleaned.addAll(list);
        continue;
      }

      final hasPaid = list.any((e) => e.status == 'paid');
      if (hasPaid) {
        // Keep paid records, retire duplicate pending records
        final paidList = list.where((e) => e.status == 'paid').toList();
        final pendingList = list.where((e) => e.status != 'paid').toList();

        for (final p in pendingList) {
          retired.add(p.id);
        }

        // If multiple paid records exist with the exact same date, amount, description and category,
        // it is an accidental double-entry/sync artifact. Keep one and retire the duplicate.
        final seenDates = <String>{};
        for (final e in paidList) {
          final dateKey = e.date.trim();
          if (dateKey.isNotEmpty && seenDates.contains(dateKey)) {
            retired.add(e.id);
          } else {
            if (dateKey.isNotEmpty) seenDates.add(dateKey);
            cleaned.add(e);
          }
        }
      } else {
        // Keep the first pending expense, retire duplicate pending entries
        cleaned.add(list.first);
        for (var i = 1; i < list.length; i++) {
          retired.add(list[i].id);
        }
      }
    }

    return AutoDeduplicationResult(
      cleaned: cleaned,
      retiredIds: retired,
    );
  }

  /// Reconciles documents in the vault, detecting and retiring duplicate tenant documents
  /// or identical uploaded files.
  static AutoDeduplicationResult<RentDoc> reconcileDocuments(List<RentDoc> docs) {
    if (docs.isEmpty) {
      return const AutoDeduplicationResult(cleaned: [], retiredIds: {});
    }

    final groups = <String, List<RentDoc>>{};
    for (final d in docs) {
      final isTenantDoc = d.tags.contains('tenant-document') ||
          (d.tenant != null && d.tenant!.trim().isNotEmpty);

      if (isTenantDoc) {
        final tName = (d.tenant ?? '').trim().toLowerCase();
        final tTitle = d.title.trim().toLowerCase();
        final tType = d.type.trim().toLowerCase();
        // Use the stored file name as identity. This collapses sync ghosts
        // (same title + same file, one missing a URI) while preserving annual
        // lease versions, whose file names differ.
        final file = d.fileName.trim().toLowerCase();
        final key =
            'tenant_${tName}_${tTitle.isNotEmpty ? tTitle : tType}_$file';
        groups.putIfAbsent(key, () => []).add(d);
      } else {
        // Non-tenant document: group by title + filename + fileUri
        final title = d.title.trim().toLowerCase();
        final file = d.fileName.trim().toLowerCase();
        final uri = (d.fileUri ?? '').trim().toLowerCase();
        if (title.isEmpty && file.isEmpty && uri.isEmpty) {
          groups.putIfAbsent('raw_${d.id}', () => []).add(d);
        } else {
          groups.putIfAbsent('doc_${title}_${file}_$uri', () => []).add(d);
        }
      }
    }

    final cleaned = <RentDoc>[];
    final retired = <String>{};

    for (final list in groups.values) {
      if (list.length <= 1) {
        cleaned.addAll(list);
        continue;
      }

      // Sort: prefer items with valid fileUri, then newest uploadedDate
      list.sort((a, b) {
        final aHasUri = a.fileUri != null && a.fileUri!.isNotEmpty ? 1 : 0;
        final bHasUri = b.fileUri != null && b.fileUri!.isNotEmpty ? 1 : 0;
        if (aHasUri != bHasUri) return bHasUri.compareTo(aHasUri);

        final aDate = DateTime.tryParse(a.uploadedDate) ?? DateTime.fromMillisecondsSinceEpoch(0);
        final bDate = DateTime.tryParse(b.uploadedDate) ?? DateTime.fromMillisecondsSinceEpoch(0);
        return bDate.compareTo(aDate);
      });

      final keep = list.first;
      cleaned.add(keep);
      for (var i = 1; i < list.length; i++) {
        retired.add(list[i].id);
      }
    }

    return AutoDeduplicationResult(
      cleaned: cleaned,
      retiredIds: retired,
    );
  }

  /// Reconciles expense categories by retiring redundant duplicates with identical names.
  static AutoDeduplicationResult<ExpenseCategory> reconcileExpenseCategories(
    List<ExpenseCategory> categories,
  ) {
    if (categories.isEmpty) {
      return const AutoDeduplicationResult(cleaned: [], retiredIds: {});
    }
    final cleaned = DefaultData.normalizedExpenseCategories(categories);
    final keptIds = cleaned.map((c) => c.id).toSet();
    final retired = categories
        .map((c) => c.id)
        .where((id) => id.isNotEmpty && !keptIds.contains(id))
        .toSet();
    return AutoDeduplicationResult(cleaned: cleaned, retiredIds: retired);
  }

  /// Reconciles payments, expenses, documents, and expense categories in-memory and records retired IDs to persistent storage.
  static Future<({
    List<Payment> payments,
    List<Expense> expenses,
    List<RentDoc> documents,
    List<ExpenseCategory> expenseCategories,
    Set<String> retiredIds,
  })> reconcileAndPersist({
    required List<Payment> payments,
    required List<Expense> expenses,
    List<RentDoc>? documents,
    List<ExpenseCategory>? expenseCategories,
    Map<String, Tenant>? tenantById,
  }) async {
    final payRes = reconcilePayments(payments, tenantById: tenantById);
    final expRes = reconcileExpenses(expenses);
    final docRes = reconcileDocuments(documents ?? const []);
    final expCatRes =
        reconcileExpenseCategories(expenseCategories ?? const []);
    final allRetired = {
      ...payRes.retiredIds,
      ...expRes.retiredIds,
      ...docRes.retiredIds,
      ...expCatRes.retiredIds,
    };

    if (allRetired.isNotEmpty) {
      debugPrint(
          '[AutoDeduplication] Silently retired ${allRetired.length} duplicate records');
      await AppStorage.trackDeletedIds(allRetired);
      await AppStorage.writeList(
        StorageKeys.payments,
        payRes.cleaned.map((p) => p.toJson()).toList(),
      );
      await AppStorage.writeList(
        StorageKeys.expenses,
        expRes.cleaned.map((e) => e.toJson()).toList(),
      );
      if (documents != null) {
        await AppStorage.writeList(
          StorageKeys.documents,
          docRes.cleaned.map((d) => d.toJson()).toList(),
        );
      }
      if (expenseCategories != null && expCatRes.retiredIds.isNotEmpty) {
        await AppStorage.writeList(
          StorageKeys.expenseCategories,
          expCatRes.cleaned.map((c) => c.toJson()).toList(),
        );
      }
    }

    return (
      payments: payRes.cleaned,
      expenses: expRes.cleaned,
      documents: docRes.cleaned,
      expenseCategories: expCatRes.cleaned,
      retiredIds: allRetired,
    );
  }
}
